    const path = repoPath(opts.contentDir, relativePath);
    const gh = encodePath(path);
    const link = (cls, href, text, data = {}) => _("a", { class: cls, href, target: "_blank", rel: "noopener noreferrer", ...data }, text);
    const editEndpoint = opts.editor && opts.suggestEndpoint ? proposeEndpoint(opts.suggestEndpoint) : "";
